:root {
  color-scheme: dark;
}

html,
body {
  margin: 0;
  height: 100%;
  background: #020617;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

.main {
  min-height: 100vh;
  background: #020617;
  color: #e5e7eb;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  place-items: center;
  padding: 24px;
}

.card {
  width: 100%;
  max-width: 640px;
  background: #020617;
  border-radius: 16px;
  border: 1px solid #1f2937;
  min-width: 0;
  padding: 18px 18px 16px;
  display: grid;
  gap: 14px;
}

.header {
  display: grid;
  gap: 4px;
}

.title {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
}

.subtitle {
  margin: 0;
  font-size: 13px;
  color: #9ca3af;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.label {
  font-size: 13px;
  color: #9ca3af;
}

.scenario {
  background: #0f172a;
  color: #e5e7eb;
  border: 1px solid #334155;
  border-radius: 8px;
  padding: 6px 8px;
  font: inherit;
}

.status-line {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 13px;
  color: #9ca3af;
}

.sync-status {
  color: #93c5fd;
}

.update-meter {
  font-size: 12px;
  color: #6b7280;
  min-height: 16px;
}

.spread {
  margin: 0;
  font-size: 13px;
  color: #e5e7eb;
  font-variant-numeric: tabular-nums;
}

.book {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  transition: opacity 120ms ease;
}

.book--stale {
  opacity: 0.55;
}

.side {
  min-width: 0;
}

.side-title {
  margin: 0 0 6px;
  font-size: 12px;
  font-weight: 600;
  color: #9ca3af;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.bids,
.asks {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 2px;
}

.level {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  padding: 4px 8px;
  border-radius: 6px;
  background: #0f172a;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}

.bid .price {
  color: #86efac;
}

.ask .price {
  color: #fca5a5;
}

.size {
  color: #e5e7eb;
}

@media (max-width: 420px) {
  .book {
    grid-template-columns: minmax(0, 1fr);
  }
}
